{"python":"rows = get_rows('supp.xls', 'Table S7')
records = []
data = []
for i, row in enumerate(rows[1:], start=2):
    if len(row) >= 6 and row[1] == 'FOLFOX':
        patient = row[0]
        score_ref = f'supp.xls/Table S7/R{i}C4'
        truth_ref = f'supp.xls/Table S7/R{i}C3'
        y = 1.0 if row[2] == 'PD' else 0.0
        x = float(row[3])
        data.append((x, y))
        records.append({
            'id': patient,
            'score': {'ref': score_ref},
            'truth': {'ref': truth_ref, 'map': {'SD/PR': 0, 'PD': 1}}
        })

# Mann-Whitney AUC with tie handling; log(IC50) is rank-equivalent to IC50.
pos = [x for x, y in data if y == 1]
neg = [x for x, y in data if y == 0]
favorable = 0.0
for p in pos:
    for n in neg:
        if p > n:
            favorable += 1.0
        elif p == n:
            favorable += 0.5
auc = favorable / (len(pos) * len(neg))
print('n=', len(data), 'PD=', len(pos), 'SD_PR=', len(neg), 'AUC=', auc)

